{
  "name": "openeuler-agent-shennong-crash-online",
  "version": "0.10.4",
  "description": "Minimal OpenCode plugin for kernel crash diagnosis using Shennong agent and core skills. (online package)",
  "keywords": [
    "shennong",
    "kernel-crash",
    "diagnosis",
    "opencode-plugin"
  ],
  "license": "MIT",
  "type": "module",
  "main": "dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "skills",
    "bin",
    "lib",
    "frameworks",
    "agent.md",
    "package-variant.json",
    "package-content-manifest.json"
  ],
  "bin": {
    "shennong-setup": "./bin/shennong-setup.mjs",
    "shennong-configure": "./bin/shennong-configure.mjs"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=20.0.0"
  },
  "dependencies": {
    "jsonc-parser": "^3.3.1"
  },
  "shennongVariant": "online",
  "wittyPackageStyle": "plain"
}
